@Component({
  selector: 'app-post-header',
  imports: [AvatarComponent],
  templateUrl: './post-header.component.html',
  styleUrl: './post-header.component.scss',
})
export class PostHeaderComponent {
  readonly author = input.required<Author>();
  readonly createdAt = input.required<string>();
}

export class NewPostFormComponent {
  readonly posted = output<{ imageUrl: string; caption: string }>();

  readonly form = new FormGroup({
    imageUrl: new FormControl('', { nonNullable: true }),
    caption: new FormControl({ value: 'Sunset', disabled: true }, { nonNullable: true }),
  });

  submit() {
    this.posted.emit(this.form.value as { imageUrl: string; caption: string });
  }
}

export class FeedPageComponent {
  private readonly store = inject(Store);
  readonly posts = this.store.selectSignal(selectAllPosts);

  sortByLikes() {
    this.posts().sort((a, b) => b.likes - a.likes);
  }
}

export const loadFeed = createEffect(
  (actions$ = inject(Actions), postsApi = inject(PostsApiService)) =>
    actions$.pipe(
      ofType(PostsActions.loadFeed),
      switchMap(() => postsApi.getFeed().pipe(
        map((posts) => PostsActions.loadFeedSuccess({ posts })),
      )),
    ),
  { functional: true },
);

export class CommentsSectionComponent {
  private readonly commentsApi = inject(CommentsApiService);
  readonly postId = input.required<string>();

  addComment(text: string) {
    this.commentsApi.add(this.postId(), text).pipe(
      map((comment) => comment.id),
    );
  }
}
